export const catalogs: Record<UiLocale, MessageCatalog> = completeCatalogs;
export function isRtl(locale: UiLocale) { return rtlLocales.has(locale); }
export function message(locale: UiLocale, key: MessageKey, values: Record<string, string | number> = {}) {
  let value = catalogs[locale][key];
  for (const [name, replacement] of Object.entries(values)) value = value.replaceAll(`{${name}}`, String(replacement));
  return value;
}
export function formatNumber(locale: UiLocale, value: number) { return new Intl.NumberFormat(locale).format(value); }
export function formatPercent(locale: UiLocale, value: number) { return new Intl.NumberFormat(locale, { style: 'percent', maximumFractionDigits: 1 }).format(value); }
export function formatDate(locale: UiLocale, value: string | number | Date | null | undefined) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat(locale, { dateStyle: 'medium', timeStyle: 'short' }).format(date); }
export function formatRelative(locale: UiLocale, seconds: number) { return new Intl.RelativeTimeFormat(locale, { numeric: 'auto' }).format(Math.round(seconds / 60), 'minute'); }
export function formatDuration(locale: UiLocale, seconds: number) { const minutes = Math.floor(seconds / 60); const remainder = Math.round(seconds % 60); return `${formatNumber(locale, minutes)}m ${formatNumber(locale, remainder)}s`; }
export function formatBytes(locale: UiLocale, bytes: number) { const units = ['B', 'KB', 'MB', 'GB']; let value = Math.max(0, bytes); let index = 0; while (value >= 1024 && index < units.length - 1) { value /= 1024; index += 1; } return `${new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)} ${units[index]}`; }
export function formatCount(locale: UiLocale, count: number, one: string, other: string) { return new Intl.PluralRules(locale).select(count) === 'one' ? `${formatNumber(locale, count)} ${one}` : `${formatNumber(locale, count)} ${other}`; }
export function formatOrdinal(locale: UiLocale, value: number) { const category = new Intl.PluralRules(locale, { type: 'ordinal' }).select(value); const suffix: Record<string, string> = { one: 'st', two: 'nd', few: 'rd' }; return `${formatNumber(locale, value)}${locale.startsWith('en') ? (suffix[category] ?? 'th') : ''}`; }
export function formatSelect(_locale: UiLocale, value: string, cases: Record<string, string>) { return cases[value] ?? cases.other ?? ''; }
export function pseudoLocalize(value: string) { return `［${value.replace(/[aeiouAEIOU]/g, (letter) => `${letter}·`)}］`; }
export function validateCatalogs() { const keys = Object.keys(en).sort(); return supportedLocales.every((locale) => Object.keys(catalogs[locale]).sort().join('|') === keys.join('|') && keys.every((key) => catalogs[locale][key as MessageKey].trim().length > 0)); }
